 "content": "from collections import Counter

def transform(grid):
    h,w=len(grid),len(grid[0])
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    # Separator lines are uniform and occur as full rows or columns.
    rowcuts=[r for r,row in enumerate(grid) if len(set(row))==1]
    colcuts=[c for c in range(w) if len({grid[r][c] for r in range(h)})==1]
    sep=grid[rowcuts[0]][0] if rowcuts else grid[0][colcuts[0]] if colcuts else None
    # Prefer uniform cuts matching separator color.
    rowcuts=[r for r in rowcuts if grid[r][0]==sep]
    colcuts=[c for c in colcuts if grid[0][c]==sep]
    def parts(n,cuts):
        ret=[]; start=0
        for cut in cuts:
            if start<cut: ret.append((start,cut))
            start=cut+1
        if start<n: ret.append((start,n))
        return ret
    rows=parts(h,rowcuts); cols=parts(w,colcuts)
    # The panel with the most non-background cells contains the motif.
    score=lambda box: sum(grid[r][c]!=bg for r in range(box[0],box[1]) for c in range(box[2],box[3]))
    boxes=[(a,b,x,y) for a,b in rows for x,y in cols]
    a,b,x,y=max(boxes,key=score)
    tile=[row[x:y] for row in grid[a:b]]
    out=[row[:] for row in grid]
    for ra,rb in rows:
      for ca,cb in cols:
        for r in range(ra,rb):
          for c in range(ca,cb):
            out[r][c]=tile[(r-ra)%len(tile)][(c-ca)%len(tile[0])]
    return out
